export const all=(n,tag)=>n?Array.from(n.getElementsByTagNameNS('*',tag)):[];
const kids=(n,tag)=>Array.from(n?.children||[]).filter(x=>!tag||x.localName===tag);
const first=(n,tag)=>all(n,tag)[0];
export const attr=(n,key)=>n?.getAttribute(key)||Array.from(n?.attributes||[]).find(a=>a.localName===key)?.value||'';
const clean=s=>String(s??'').trim();
export function xml(bytes){const d=new DOMParser().parseFromString(new TextDecoder().decode(bytes),'application/xml');if(d.getElementsByTagName('parsererror').length)throw Error('문서 구조를 읽지 못했습니다. 파일을 다시 저장해 주세요.');return d}
function resolve(part,target){const out=target.startsWith('/')?[]:part.split('/').slice(0,-1);for(const segment of target.split('/')){if(segment==='..')out.pop();else if(segment&&segment!=='.')out.push(segment)}return out.join('/')}
function rels(bytes,part){const dir=part.slice(0,part.lastIndexOf('/')+1),name=part.slice(part.lastIndexOf('/')+1),data=bytes[`${dir}_rels/${name}.rels`];return new Map(data?all(xml(data),'Relationship').filter(r=>attr(r,'TargetMode')!=='External').map(r=>[attr(r,'Id'),resolve(part,attr(r,'Target'))]):[])}
export function math(n){
 const k=n?.localName;const get=tag=>kids(n,tag).map(math).join(' ');const join=()=>kids(n).filter(c=>!c.localName.endsWith('Pr')).map(math).join('');
 if(!n)return'';if(k==='t')return n.textContent;if(k==='f'){const num=get('num'),den=get('den');return attr(first(first(n,'fPr'),'type'),'val')==='noBar'?` 상하 배치 시작. 위 항 ${num}. 아래 항 ${den}. 배치 끝. `:` 분수 시작. 분자 ${num}. 분모 ${den}. 분수 끝. `}
 if(['sSup','sSub','sSubSup'].includes(k))return ` ${get('e')}${k!=='sSup'?`, 아래첨자 ${get('sub')}, 아래첨자 끝`:''}${k!=='sSub'?`, 위첨자 ${get('sup')}, 위첨자 끝`:''} `;
 if(k==='rad')return ` 근호 시작. ${get('deg')?'근 지수 '+get('deg')+'. ':''}근호 안 ${get('e')}. 근호 끝. `;
 if(k==='d'){const props=first(n,'dPr');const begin=attr(first(props,'begChr'),'val')||'(';const end=attr(first(props,'endChr'),'val')||')';const names={'(':'소괄호',')':'소괄호','[':'대괄호',']':'대괄호','{':'중괄호','}':'중괄호','|':'세로선','‖':'이중 세로선'};return ` ${names[begin]||begin} 시작. ${get('e')}. ${names[end]||end} 끝. `;}
 if(k==='limLow'||k==='limUpp')return ` ${get('e')}. ${k==='limLow'?'아래':'위'} 극한 조건 ${get('lim')}. 조건 끝. `;
 if(k==='func')return ` 함수 ${get('fName')}. 인수 시작 ${get('e')}. 인수 끝. `;
 if(k==='acc')return ` 위에 ${attr(first(first(n,'accPr'),'chr'),'val')||'강조 기호'}가 있는 식. ${get('e')}. 식 끝. `;
 if(k==='bar')return ` ${attr(first(first(n,'barPr'),'pos'),'val')==='bot'?'아래':'위'} 막대가 있는 식. ${get('e')}. 식 끝. `;
 if(k==='nary')return ` ${attr(first(first(n,'naryPr'),'chr'),'val')||'합 기호'} ${get('sub')?'아래 범위 '+get('sub')+'. ':''}${get('sup')?'위 범위 '+get('sup')+'. ':''}대상 ${get('e')}. 연산 범위 끝. `;
 if(k==='m')return ` 행렬 시작. ${kids(n,'mr').map((r,i)=>`${i+1}행. ${kids(r,'e').map((c,j)=>`${j+1}열 ${math(c)}`).join(', ')}`).join('. ')}. 행렬 끝. `;
 if(k==='eqArr')return ` 수식 묶음. ${kids(n,'e').map(math).join('. ')}. `;
 return join();
}
function read(n){if(!n)return'';if(n.localName==='oMath')return math(n);if(n.localName==='t')return n.textContent;if(n.localName==='footnoteReference')return ` (각주 ${attr(n,'id')} 참조) `;if(n.localName==='endnoteReference')return ` (미주 ${attr(n,'id')} 참조) `;if(['br','cr'].includes(n.localName))return'\n';if(n.localName==='tab')return'\t';if(['drawing','pict'].includes(n.localName))return'';if(n.localName==='AlternateContent'){const choices=kids(n);return read(choices.find(x=>x.localName==='Choice')||choices[0])}return kids(n).map(read).join('')}
function paragraphs(n){return all(n,'p').filter(p=>{let a=p.parentElement;while(a&&a!==n){if(a.localName==='p')return false;a=a.parentElement}return true}).map(read).filter(clean).join('\n')}
export function readTable(n,warnings){
 const word=n.namespaceURI?.includes('wordprocessingml')||n.nodeName?.startsWith('w:');const rows=kids(n,'tr'),grid=[],cells=[];let active=new Map(),merged=false;
 rows.forEach((tr,r)=>{grid[r] ||= [];let c=word?Number(attr(first(first(tr,'trPr'),'gridBefore'),'val')||0):0;const next=new Map();
  kids(tr,'tc').forEach(tc=>{const props=kids(tc,'tcPr')[0];const cs=Math.max(1,Number(word?attr(first(props,'gridSpan'),'val')||1:attr(tc,'gridSpan')||1));let rs=word?1:Math.max(1,Number(attr(tc,'rowSpan')||1));const text=paragraphs(tc);const vm=word?first(props,'vMerge'):null;const key=`${c}:${cs}`;
   if(word&&vm&&attr(vm,'val')!=='restart'&&active.has(key)){const a=active.get(key);a.rs++;next.set(key,a);for(let j=0;j<cs;j++)grid[r][c+j]=a;if(text&&text!==a.text)warnings.add('세로 병합의 연속 셀에 별도 텍스트가 있습니다: '+text);c+=cs;return}
   if(!word&&(attr(tc,'hMerge')==='1'||attr(tc,'vMerge')==='1'||attr(tc,'hMerge')==='true'||attr(tc,'vMerge')==='true')){if(!grid[r][c])warnings.add('병합된 표 셀의 시작 위치를 찾지 못했습니다.');c++;return}
   if(word&&vm&&attr(vm,'val')!=='restart')warnings.add('표의 세로 병합 시작 셀을 찾지 못했습니다. 해당 값은 독립 셀로 읽습니다.');
   if(!Number.isInteger(cs)||!Number.isInteger(rs)||cs>512||rs>512||c+cs>512||r+rs>5000)throw Error('표의 행·열 범위가 너무 큽니다. 표를 나누어 주세요.');const a={r,c,cs,rs,text};cells.push(a);for(let y=r;y<r+rs;y++){grid[y] ||= [];for(let x=c;x<c+cs;x++)grid[y][x]=a}if(word&&vm)next.set(key,a);if(cs>1||rs>1||vm)merged=true;c+=word?cs:1;
  });active=next;
 });const width=Math.max(all(first(n,'tblGrid'),'gridCol').length,...grid.map(r=>r.length),0);const out=grid.map(row=>Array.from({length:width},(_,c)=>row[c]?.text||''));
 let headerRows=0;for(const tr of rows){if(first(first(tr,'trPr'),'tblHeader'))headerRows++;else break}
 return{kind:'table',rows:out,grid,cells,merged,headerRows};
}
function points(n){const result=new Map();if(!n)return result;const levels=all(n,'lvl');if(levels.length){for(const lvl of levels)for(const p of kids(lvl,'pt')){const idx=Number(attr(p,'idx'));const value=first(p,'v')?.textContent||'';result.set(idx,[result.get(idx),value].filter(Boolean).join(' / '))}}else for(const p of all(n,'pt'))result.set(Number(attr(p,'idx')),first(p,'v')?.textContent||'');return result}
function formatValue(raw,format){if(raw===undefined||raw==='')return'';const n=Number(raw);if(!Number.isFinite(n))return `원문 값 ${raw}`;if(/^[0#.,]+%$/.test(format)){const digits=(format.split('.')[1]||'').replace('%','').length;return(n*100).toFixed(Math.min(digits,8))+'%'}return raw}
function chart(bytes,path,source,warnings){
 if(!bytes[path])return[{kind:'visual',source,text:'차트 데이터가 파일에 포함되어 있지 않습니다.',unresolved:true}];const d=xml(bytes[path]),plot=first(d,'plotArea');const titleNode=kids(first(d,'chart'),'title')[0];const title=paragraphs(titleNode)||[...points(titleNode).values()].join(' ')||'차트';const blocks=[{kind:'paragraph',source,method:'차트 데이터',text:`${title}. 문서에 저장된 차트 데이터를 읽습니다.`}];let found=0;
 for(const group of kids(plot)){const series=kids(group,'ser');if(!series.length)continue;const kind={barChart:'막대 차트',lineChart:'꺾은선 차트',pieChart:'원형 차트',scatterChart:'산점도',areaChart:'영역 차트',doughnutChart:'도넛 차트',bubbleChart:'거품 차트'}[group.localName]||'차트';
  series.forEach((s,i)=>{const nameNode=kids(s,'tx')[0];const name=kids(nameNode,'v')[0]?.textContent||[...points(nameNode).values()][0]||`계열 ${i+1}`;const scatter=!!kids(s,'xVal').length;const cats=points(kids(s,scatter?'xVal':'cat')[0]),valNode=kids(s,scatter?'yVal':'val')[0],values=points(valNode),size=points(kids(s,'bubbleSize')[0]);const fmt=first(valNode,'formatCode')?.textContent||'';const indices=[...new Set([...cats.keys(),...values.keys(),...size.keys()])].sort((a,b)=>a-b);if(!indices.length){warnings.add(`${source}: ${name} 차트의 저장된 값을 찾지 못했습니다.`);blocks.push({kind:'visual',source,text:`${kind}, ${name}. 제목은 읽었으나 수치 데이터는 파일에 없습니다.`,unresolved:true});return}
   const rows=[[scatter?'X 값':'범주',scatter?'Y 값':'값',...(size.size?['크기']:[])],...indices.map(j=>[cats.get(j)||`항목 ${j+1}`,formatValue(values.get(j),fmt),...(size.size?[size.get(j)||'']:[])])];const axisTitles=kids(plot).filter(a=>/Ax$/.test(a.localName)).map(a=>paragraphs(kids(a,'title')[0])).filter(Boolean);const note=[axisTitles.length?'축 제목: '+axisTitles.join(', ')+'.':'',fmt&&!/^(General|[0#.,]+%)$/.test(fmt)?'숫자는 저장된 원시 값으로 읽습니다. 표시 형식: '+fmt+'.':''].filter(Boolean).join(' ');blocks.push({kind:'table',rows,title:`${kind}, ${name}`,source,method:'차트 데이터',headerRows:1,note});found++;
  });
 }if(!found&&!blocks.some(b=>b.unresolved))blocks.push({kind:'visual',source,text:'차트의 제목만 읽었습니다. 지원되는 계열 데이터를 찾지 못했습니다.',unresolved:true});return blocks;
}
function smartArt(bytes,path,source){if(!bytes[path])return[];const d=xml(bytes[path]);const labels=new Map(all(d,'pt').map(p=>[attr(p,'modelId'),paragraphs(kids(p,'t')[0])]));const out=[];if(![...labels.values()].some(Boolean))return[{kind:'visual',source,text:'도식 구조는 있지만 읽을 수 있는 항목 이름을 찾지 못했습니다.',unresolved:true}];const edges=all(d,'cxn').filter(c=>attr(c,'type')==='parOf');for(const c of edges){const a=labels.get(attr(c,'srcId')),b=labels.get(attr(c,'destId'));if(a&&b)out.push(`${a}의 하위 항목은 ${b}입니다.`)}return[{kind:'paragraph',source,method:'도식 구조',text:`도식의 항목: ${[...new Set([...labels.values()].filter(Boolean))].join(', ')}.${out.length?' '+out.join(' '):' 항목 간 명시적인 상하 관계는 없습니다.'}`}];}
function picture(bytes,relationships,n,source){const prop=first(n,'docPr')||first(n,'cNvPr');const meaningful=x=>x&&!/^(?:image|picture|그림|사진)\s*\d*$/i.test(x.trim())&&!/^[^\n]+\.(?:png|jpe?g|gif|bmp|webp|tiff?|svg|emf|wmf)$/i.test(x.trim());const alt=[attr(prop,'descr'),attr(prop,'title')].filter((x,i,a)=>meaningful(x)&&a.indexOf(x)===i).join('. ');const imagePath=relationships.get(attr(first(n,'blip'),'embed'));return{kind:'visual',source,text:alt?`작성자가 제공한 그림 설명: ${alt}`:'',method:alt?'대체 설명':'',image:bytes[imagePath]?{bytes:bytes[imagePath],path:imagePath}:null,unresolved:!alt};}
function graphics(bytes,part,n,source,warnings){if(all(n,'decorative').some(d=>['1','true'].includes(attr(d,'val'))))return[];const relationships=rels(bytes,part),out=[];for(const c of all(n,'chart')){const path=relationships.get(attr(c,'id'));if(path)out.push(...chart(bytes,path,source,warnings))}for(const dm of all(n,'relIds')){const path=relationships.get(attr(dm,'dm'));if(path)out.push(...smartArt(bytes,path,source))}if(!out.length&&(first(n,'blip')||n.localName==='pic'))out.push(picture(bytes,relationships,n,source));return out;}
export async function openOffice(file){const {unzipSync}=await import('./vendor/fflate.mjs');let total=0,large=false;let bytes;try{bytes=unzipSync(new Uint8Array(await file.arrayBuffer()),{filter:e=>{if(!/^(word|ppt)\//.test(e.name)||!(/\.xml(?:\.rels)?$|\.rels$|\.(png|jpe?g|gif|bmp|webp|tiff?|emf|wmf|svg)$/i.test(e.name)))return false;total+=e.originalSize;if(total>100*1024*1024||e.originalSize>30*1024*1024){large=true;return false}return true}})}catch{throw Error('압축 문서를 읽지 못했습니다. 암호가 없는 파일을 올려 주세요.')}if(large)throw Error('문서 내부 용량이 너무 큽니다. 자료를 나눠 주세요.');return bytes}
export function extractOffice(bytes,ext,warnings){const blocks=[];
 if(ext==='docx'){
  if(!bytes['word/document.xml'])throw Error('올바른 DOCX가 아닙니다.');const d=xml(bytes['word/document.xml']);let number=0;
  for(const node of kids(first(d,'body'))){if(node.localName==='tbl'){blocks.push({...readTable(node,warnings),source:`표 ${++number}`});continue}if(node.localName!=='p')continue;let text=read(node);if(first(node,'numPr'))text=`목록 ${Number(attr(first(node,'ilvl'),'val')||0)+1}단계. ${text}`;const style=attr(first(node,'pStyle'),'val');if(clean(text))blocks.push({kind:/heading|title|제목/i.test(style)?'heading':'paragraph',level:Number(style.match(/\d/)?.[0]||1),text});for(const drawing of all(node,'drawing'))blocks.push(...graphics(bytes,'word/document.xml',drawing,`본문 그림 ${++number}`,warnings));}
  for(const [part,label]of [['footnotes','각주'],['endnotes','미주']])if(bytes[`word/${part}.xml`])for(const n of all(xml(bytes[`word/${part}.xml`]),part.slice(0,-1))){if(Number(attr(n,'id'))>0)blocks.push({kind:'paragraph',text:`${label} ${attr(n,'id')}. ${paragraphs(n)}`})}
 }else{
  let paths=Object.keys(bytes).filter(p=>/^ppt\/slides\/slide\d+\.xml$/.test(p)).sort((a,b)=>Number(a.match(/\d+/)[0])-Number(b.match(/\d+/)[0]));const r=rels(bytes,'ppt/presentation.xml');if(bytes['ppt/presentation.xml']){const ordered=all(xml(bytes['ppt/presentation.xml']),'sldId').map(n=>r.get(Array.from(n.attributes).find(a=>a.localName==='id'&&a.namespaceURI?.includes('relationships'))?.value)).filter(p=>bytes[p]);if(ordered.length===paths.length)paths=ordered}
  if(!paths.length)throw Error('슬라이드를 찾지 못했습니다.');paths.forEach((part,i)=>{const d=xml(bytes[part]);const source=`슬라이드 ${i+1}`;blocks.push({kind:'heading',text:source,level:1});const flatten=n=>kids(n).flatMap(c=>c.localName==='grpSp'?flatten(c):c.localName==='AlternateContent'?flatten(kids(c,'Choice')[0]||kids(c,'Fallback')[0]):['sp','pic','graphicFrame','cxnSp'].includes(c.localName)?[c]:[]);const shapes=flatten(first(d,'spTree'));const labels=new Map(shapes.map(n=>[attr(first(n,'cNvPr'),'id'),paragraphs(n)]));
   shapes.sort((a,b)=>{const title=n=>all(n,'ph').some(p=>['title','ctrTitle'].includes(attr(p,'type')));return Number(title(b))-Number(title(a))||Number(attr(first(a,'off'),'y'))-Number(attr(first(b,'off'),'y'))||Number(attr(first(a,'off'),'x'))-Number(attr(first(b,'off'),'x'))});
   for(const n of shapes){const prop=first(n,'cNvPr'),loc=`${source} · 개체 ${attr(prop,'id')||''}`;
    if(n.localName==='cxnSp'){const start=labels.get(attr(first(n,'stCxn'),'id')),end=labels.get(attr(first(n,'endCxn'),'id'));if(start&&end){const arrow=t=>['triangle','stealth','arrow'].includes(attr(first(n,t),'type'));const head=arrow('headEnd'),tail=arrow('tailEnd');const text=head&&tail?`${start}와 ${end}가 양방향으로 연결됩니다.`:head?`${end}에서 ${start}로 화살표가 이어집니다.`:tail?`${start}에서 ${end}로 화살표가 이어집니다.`:`${start}와 ${end}가 선으로 연결되어 있습니다.`;blocks.push({kind:'paragraph',source:loc,method:'연결선 구조',text})}else warnings.add(`${source}: 연결선 하나의 연결 대상 정보가 부족합니다.`);continue}
    if(first(n,'tbl')){for(const t of all(n,'tbl'))blocks.push({...readTable(t,warnings),source:loc});continue}
    const g=graphics(bytes,part,n,loc,warnings);if(g.length){blocks.push(...g);continue}
    const text=paragraphs(n);if(clean(text)){const title=all(n,'ph').some(p=>['title','ctrTitle'].includes(attr(p,'type')));blocks.push({kind:title?'heading':'paragraph',level:2,text,source:loc})}else if(n.localName==='graphicFrame')blocks.push({kind:'visual',source:loc,text:'이 개체에서 지원되는 구조나 이미지 데이터를 찾지 못했습니다.',unresolved:true});
   }
  });
 }return blocks;
}

